#include <iomanip>
#include <iostream>
int main() {
    const double l1_lookup = 1.0;
    const double l1_miss = 0.10;
    const double l2_lookup = 6.0;
    const double l2_local_miss = 0.25;
    const double memory_extra = 80.0;
    const double after_l1_miss = l2_lookup + l2_local_miss * memory_extra;
    const double average = l1_lookup + l1_miss * after_l1_miss;
    std::cout << std::fixed << std::setprecision(2);
    std::cout << "L1 miss path=" << after_l1_miss << " ns\n";
    std::cout << "modeled AMAT=" << average << " ns\n";
}

#include <cstddef>
#include <iostream>
std::size_t cost(std::size_t records, std::size_t batch) {
    // The caller supplies a positive batch size in this small model.
    const auto batches = records / batch + (records % batch != 0);
    return batches * 5 + records * 2;
}
int main() {
    const std::size_t records = 10;
    std::cout << "one-record batches=" << cost(records, 1) << '\n';
    std::cout << "up-to-four batches=" << cost(records, 4) << '\n';
    std::cout << "empty work=" << cost(0, 4) << '\n';
}

